-- Non-posting estimates: immutable revisions with deferred build/seal obligations.
CREATE TABLE sales_estimate(id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES ledger_company(id),identity_id TEXT NOT NULL UNIQUE REFERENCES documents_documentidentity(id),creation_digest TEXT NOT NULL CHECK(length(creation_digest)=64),revision INTEGER NOT NULL CHECK(revision>=1)) STRICT, WITHOUT ROWID;
CREATE TABLE sales_estimaterevision(id TEXT PRIMARY KEY,estimate_id TEXT NOT NULL REFERENCES sales_estimate(id),number INTEGER NOT NULL CHECK(number>=1),customer_id TEXT NOT NULL REFERENCES directory_customer(id),date TEXT NOT NULL CHECK(date(date) IS date),expiry TEXT CHECK(expiry IS NULL OR (date(expiry) IS expiry AND expiry>=date)),state TEXT NOT NULL CHECK(state IN('DRAFT','ACCEPTED','DECLINED','CANCELLED')),total INTEGER NOT NULL CHECK(total BETWEEN 0 AND 9999999999999999),data TEXT NOT NULL CHECK(json_valid(data)),actor_id TEXT NOT NULL REFERENCES fb_user(id),UNIQUE(estimate_id,number)) STRICT, WITHOUT ROWID;
CREATE TABLE sales_estimateline(id TEXT PRIMARY KEY,revision_id TEXT NOT NULL REFERENCES sales_estimaterevision(id),position INTEGER NOT NULL CHECK(position BETWEEN 1 AND 50),item_id TEXT REFERENCES directory_item(id),income_account_id TEXT REFERENCES ledger_account(id),expense_account_id TEXT REFERENCES ledger_account(id),amount INTEGER NOT NULL CHECK(amount BETWEEN 0 AND 9999999999999999),taxable INTEGER NOT NULL CHECK(taxable IN(0,1)),data TEXT NOT NULL CHECK(json_valid(data)),UNIQUE(revision_id,position)) STRICT, WITHOUT ROWID;
CREATE TABLE sales_estimateconversion(id TEXT PRIMARY KEY,estimate_id TEXT NOT NULL UNIQUE REFERENCES sales_estimate(id),revision_id TEXT NOT NULL UNIQUE REFERENCES sales_estimaterevision(id),invoice_id TEXT NOT NULL UNIQUE REFERENCES sales_invoice(id),digest TEXT NOT NULL CHECK(length(digest)=64)) STRICT, WITHOUT ROWID;
CREATE TABLE estimate_seal(kind TEXT NOT NULL CHECK(kind IN('head','revision')),doc_id TEXT NOT NULL,PRIMARY KEY(kind,doc_id)) STRICT, WITHOUT ROWID;
CREATE TABLE estimate_seal_due(kind TEXT NOT NULL,doc_id TEXT NOT NULL,PRIMARY KEY(kind,doc_id),FOREIGN KEY(kind,doc_id) REFERENCES estimate_seal(kind,doc_id) DEFERRABLE INITIALLY DEFERRED) STRICT, WITHOUT ROWID;
CREATE TRIGGER fb_estimate_root_insert BEFORE INSERT ON sales_estimate BEGIN
 SELECT RAISE(ABORT,'estimate_identity: Invalid or reused estimate identity') WHERE NEW.revision<>1 OR EXISTS(SELECT 1 FROM sales_estimate WHERE id=NEW.id OR identity_id=NEW.identity_id) OR NOT EXISTS(SELECT 1 FROM documents_documentidentity WHERE id=NEW.identity_id AND company_id=NEW.company_id AND kind='EST');
END;
CREATE TRIGGER fb_estimate_root_update BEFORE UPDATE ON sales_estimate BEGIN
 SELECT RAISE(ABORT,'estimate_identity: Estimate identity is permanent') WHERE NEW.id IS NOT OLD.id OR NEW.company_id IS NOT OLD.company_id OR NEW.identity_id IS NOT OLD.identity_id OR NEW.creation_digest IS NOT OLD.creation_digest OR NEW.revision<>OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM sales_estimaterevision r JOIN estimate_seal s ON s.kind='revision' AND s.doc_id=r.id WHERE r.estimate_id=OLD.id AND r.number=OLD.revision);
END;
CREATE TRIGGER fb_estimate_root_due_insert AFTER INSERT ON sales_estimate BEGIN INSERT INTO estimate_seal_due VALUES('head',NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_estimate_root_due_update AFTER UPDATE ON sales_estimate BEGIN INSERT INTO estimate_seal_due VALUES('head',NEW.id||':'||NEW.revision); END;
CREATE TRIGGER fb_estimate_revision_insert BEFORE INSERT ON sales_estimaterevision BEGIN
 SELECT RAISE(ABORT,'estimate_history: Invalid estimate revision') WHERE EXISTS(SELECT 1 FROM sales_estimaterevision WHERE id=NEW.id OR (estimate_id=NEW.estimate_id AND number=NEW.number)) OR NOT EXISTS(SELECT 1 FROM sales_estimate e JOIN directory_customer c ON c.id=NEW.customer_id WHERE e.id=NEW.estimate_id AND e.revision=NEW.number AND c.company_id=e.company_id) OR NOT fb_sales_header_ok('invoice',NEW.data) OR json_extract(NEW.data,'$.id') IS NOT NEW.id OR json_extract(NEW.data,'$.number') IS NOT NEW.number OR json_extract(NEW.data,'$.customer_id') IS NOT NEW.customer_id OR json_extract(NEW.data,'$.date') IS NOT NEW.date OR json_extract(NEW.data,'$.expiry') IS NOT NEW.expiry OR json_extract(NEW.data,'$.state') IS NOT NEW.state OR fb_sales_money(json_quote(json_extract(NEW.data,'$.total'))) IS NOT NEW.total;
 SELECT RAISE(ABORT,'estimate_transition: Invalid state transition') WHERE NOT fb_estimate_transition_ok(coalesce((SELECT state FROM sales_estimaterevision WHERE estimate_id=NEW.estimate_id AND number=NEW.number-1),''),NEW.state,json_extract(NEW.data,'$.action'),json_extract(NEW.data,'$.reason'));
 SELECT RAISE(ABORT,'estimate_history_copy: State changes preserve all financial evidence') WHERE NEW.number>1 AND json_extract(NEW.data,'$.action')<>'revised' AND json_remove(NEW.data,'$.id','$.number','$.state','$.action','$.reason','$.actor_name') IS NOT (SELECT json_remove(data,'$.id','$.number','$.state','$.action','$.reason','$.actor_name') FROM sales_estimaterevision WHERE estimate_id=NEW.estimate_id AND number=NEW.number-1);
END;
CREATE TRIGGER fb_estimate_revision_due AFTER INSERT ON sales_estimaterevision BEGIN INSERT INTO estimate_seal_due VALUES('revision',NEW.id); END;
CREATE TRIGGER fb_estimate_line_insert BEFORE INSERT ON sales_estimateline BEGIN
 SELECT RAISE(ABORT,'estimate_line: Invalid or sealed estimate line') WHERE EXISTS(SELECT 1 FROM sales_estimateline WHERE id=NEW.id OR (revision_id=NEW.revision_id AND position=NEW.position)) OR EXISTS(SELECT 1 FROM estimate_seal WHERE kind='revision' AND doc_id=NEW.revision_id) OR NOT EXISTS(SELECT 1 FROM sales_estimaterevision r JOIN sales_estimate e ON e.id=r.estimate_id WHERE r.id=NEW.revision_id AND e.revision=r.number AND (NEW.item_id IS NULL OR EXISTS(SELECT 1 FROM directory_item WHERE id=NEW.item_id AND company_id=e.company_id)) AND (NEW.income_account_id IS NULL OR EXISTS(SELECT 1 FROM ledger_account WHERE id=NEW.income_account_id AND company_id=e.company_id)) AND (NEW.expense_account_id IS NULL OR EXISTS(SELECT 1 FROM ledger_account WHERE id=NEW.expense_account_id AND company_id=e.company_id))) OR NOT fb_sales_line_ok(NEW.data) OR json_extract(NEW.data,'$.position') IS NOT NEW.position OR json_extract(NEW.data,'$.item_id') IS NOT NEW.item_id OR json_extract(NEW.data,'$.income_account_id') IS NOT NEW.income_account_id OR json_extract(NEW.data,'$.expense_account_id') IS NOT NEW.expense_account_id OR fb_sales_money(json_quote(json_extract(NEW.data,'$.amount'))) IS NOT NEW.amount OR json_extract(NEW.data,'$.taxable') IS NOT NEW.taxable;
END;
CREATE TRIGGER fb_estimate_seal BEFORE INSERT ON estimate_seal BEGIN
 SELECT RAISE(ABORT,'estimate_seal: Invalid revision seal') WHERE NEW.kind='revision' AND NOT EXISTS(SELECT 1 FROM sales_estimaterevision r WHERE r.id=NEW.doc_id AND json_extract(r.data,'$.company_snapshot.id')=(SELECT company_id FROM sales_estimate WHERE id=r.estimate_id) AND fb_sales_document_ok(json_set(r.data,'$.state','DRAFT'),(SELECT json_group_array(json(l.data)) FROM (SELECT data FROM sales_estimateline WHERE revision_id=r.id ORDER BY position) l),r.total));
 SELECT RAISE(ABORT,'estimate_history_copy: State changes preserve every line') WHERE NEW.kind='revision' AND EXISTS(SELECT 1 FROM sales_estimaterevision r WHERE r.id=NEW.doc_id AND r.number>1 AND json_extract(r.data,'$.action')<>'revised' AND (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT data FROM sales_estimateline WHERE revision_id=r.id ORDER BY position) l) IS NOT (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT l.data FROM sales_estimateline l JOIN sales_estimaterevision p ON p.id=l.revision_id WHERE p.estimate_id=r.estimate_id AND p.number=r.number-1 ORDER BY l.position) l));
 SELECT RAISE(ABORT,'estimate_seal: Invalid head seal') WHERE NEW.kind='head' AND NOT EXISTS(SELECT 1 FROM sales_estimate e JOIN sales_estimaterevision r ON r.estimate_id=e.id AND r.number=e.revision JOIN estimate_seal s ON s.kind='revision' AND s.doc_id=r.id WHERE NEW.doc_id=e.id||':'||e.revision);
 SELECT RAISE(ABORT,'estimate_seal: Duplicate seal') WHERE EXISTS(SELECT 1 FROM estimate_seal WHERE kind=NEW.kind AND doc_id=NEW.doc_id);
END;
CREATE TRIGGER fb_estimate_conversion_insert BEFORE INSERT ON sales_estimateconversion BEGIN
 SELECT RAISE(ABORT,'estimate_conversion: Invalid or duplicate conversion') WHERE EXISTS(SELECT 1 FROM sales_estimateconversion WHERE id=NEW.id OR estimate_id=NEW.estimate_id OR revision_id=NEW.revision_id OR invoice_id=NEW.invoice_id) OR NOT EXISTS(SELECT 1 FROM sales_estimate e JOIN sales_estimaterevision r ON r.id=NEW.revision_id AND r.estimate_id=e.id JOIN sales_invoice i ON i.id=NEW.invoice_id WHERE e.id=NEW.estimate_id AND e.revision=r.number AND r.state='ACCEPTED' AND i.company_id=e.company_id AND i.creation_digest=NEW.digest);
 SELECT RAISE(ABORT,'estimate_conversion_copy: Conversion must preserve the selected estimate') WHERE EXISTS(SELECT 1 FROM sales_estimaterevision r JOIN sales_invoicerevision i ON i.invoice_id=NEW.invoice_id AND i.number=1 WHERE r.id=NEW.revision_id AND (json_remove(i.data,'$.id','$.number','$.actor_name','$.state','$.action','$.reason','$.date','$.expiry','$.due_date','$.journal_id','$.reversal_id','$.review_digest') IS NOT json_remove(r.data,'$.id','$.number','$.actor_name','$.state','$.action','$.reason','$.date','$.expiry','$.due_date','$.journal_id','$.reversal_id','$.review_digest') OR (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT data FROM sales_invoiceline WHERE revision_id=i.id ORDER BY position) l) IS NOT (SELECT json_group_array(json_remove(l.data,'$.origin_position','$.origin_revision_id')) FROM (SELECT data FROM sales_estimateline WHERE revision_id=r.id ORDER BY position) l)));
END;
CREATE TRIGGER fb_sales_estimate_delete BEFORE DELETE ON sales_estimate BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimaterevision_update BEFORE UPDATE ON sales_estimaterevision BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimaterevision_delete BEFORE DELETE ON sales_estimaterevision BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimateline_update BEFORE UPDATE ON sales_estimateline BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimateline_delete BEFORE DELETE ON sales_estimateline BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimateconversion_update BEFORE UPDATE ON sales_estimateconversion BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_sales_estimateconversion_delete BEFORE DELETE ON sales_estimateconversion BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_estimate_seal_update BEFORE UPDATE ON estimate_seal BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_estimate_seal_delete BEFORE DELETE ON estimate_seal BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_estimate_seal_due_update BEFORE UPDATE ON estimate_seal_due BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_estimate_seal_due_delete BEFORE DELETE ON estimate_seal_due BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate evidence is permanent'); END;
CREATE TRIGGER fb_estimate_parent_directory_customer_delete BEFORE DELETE ON directory_customer WHEN EXISTS(SELECT 1 FROM sales_estimaterevision WHERE customer_id=OLD.id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_directory_customer_update BEFORE UPDATE OF id,company_id ON directory_customer WHEN (EXISTS(SELECT 1 FROM sales_estimaterevision WHERE customer_id=OLD.id)) AND (NEW.id IS NOT OLD.id OR NEW.company_id IS NOT OLD.company_id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_directory_item_delete BEFORE DELETE ON directory_item WHEN EXISTS(SELECT 1 FROM sales_estimateline WHERE item_id=OLD.id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_directory_item_update BEFORE UPDATE OF id,company_id ON directory_item WHEN (EXISTS(SELECT 1 FROM sales_estimateline WHERE item_id=OLD.id)) AND (NEW.id IS NOT OLD.id OR NEW.company_id IS NOT OLD.company_id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_ledger_account_delete BEFORE DELETE ON ledger_account WHEN EXISTS(SELECT 1 FROM sales_estimateline WHERE income_account_id=OLD.id OR expense_account_id=OLD.id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_ledger_account_update BEFORE UPDATE OF id,company_id ON ledger_account WHEN (EXISTS(SELECT 1 FROM sales_estimateline WHERE income_account_id=OLD.id OR expense_account_id=OLD.id)) AND (NEW.id IS NOT OLD.id OR NEW.company_id IS NOT OLD.company_id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_fb_user_delete BEFORE DELETE ON fb_user WHEN EXISTS(SELECT 1 FROM sales_estimaterevision WHERE actor_id=OLD.id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_parent_fb_user_update BEFORE UPDATE OF id ON fb_user WHEN (EXISTS(SELECT 1 FROM sales_estimaterevision WHERE actor_id=OLD.id)) AND (NEW.id IS NOT OLD.id) BEGIN SELECT RAISE(ABORT,'estimate_parent: Estimate reference identity is permanent'); END;
CREATE TRIGGER fb_estimate_key_sales_estimate BEFORE INSERT ON sales_estimate WHEN length(CAST(NEW.id AS BLOB))<>36 OR instr(NEW.id,char(0))<>0 OR NEW.id NOT GLOB '????????-????-????-????-????????????' OR length(replace(NEW.id,'-',''))<>32 OR replace(NEW.id,'-','') GLOB '*[^0-9a-f]*' BEGIN SELECT RAISE(ABORT,'estimate_key: Invalid canonical estimate key'); END;
