CREATE TRIGGER fb_json_sales_estimateline_insert BEFORE INSERT ON sales_estimateline BEGIN SELECT RAISE(ABORT,'duplicate_json: Invalid or duplicate JSON keys') WHERE NOT fb_json_unique_keys(NEW.data); END;
CREATE TRIGGER fb_json_sales_estimateline_update BEFORE UPDATE ON sales_estimateline BEGIN SELECT RAISE(ABORT,'duplicate_json: Invalid or duplicate JSON keys') WHERE NOT fb_json_unique_keys(NEW.data); END;
CREATE TRIGGER fb_json_sales_estimaterevision_insert BEFORE INSERT ON sales_estimaterevision BEGIN SELECT RAISE(ABORT,'duplicate_json: Invalid or duplicate JSON keys') WHERE NOT fb_json_unique_keys(NEW.data); END;
CREATE TRIGGER fb_json_sales_estimaterevision_update BEFORE UPDATE ON sales_estimaterevision BEGIN SELECT RAISE(ABORT,'duplicate_json: Invalid or duplicate JSON keys') WHERE NOT fb_json_unique_keys(NEW.data); END;
CREATE TRIGGER fb_json_estimate_seal BEFORE INSERT ON estimate_seal BEGIN SELECT RAISE(ABORT,'duplicate_json: Invalid or duplicate JSON keys') WHERE EXISTS(SELECT 1 FROM fb_json_invalid); END;

CREATE TRIGGER fb_estimate_due_insert BEFORE INSERT ON estimate_seal_due WHEN EXISTS(SELECT 1 FROM estimate_seal_due WHERE kind=NEW.kind AND doc_id=NEW.doc_id) BEGIN SELECT RAISE(ABORT,'estimate_history: Estimate seal obligations are permanent'); END;
